function topicGroupText(topic){return arr(topic?.relevantGroups).length?arr(topic.relevantGroups).map(x=>`${groupLabel(x.groupCode)} ${x.ratio}%`).join(' · '):tr('No single functional group is foregrounded.','当前没有单一功能组明显前景化。')}
function topicTenGodText(topic){const gods=arr(topic?.relevantTenGods).slice(0,4);return gods.length?gods.map(x=>`${tenGodLabel(x.tenGodCode)} ${x.ratio}%${x.visibleCount?tr(' visible',' 透干'):''}`).join(' · '):tr('No specific Ten-God point is foregrounded for this topic.','这个主题目前没有特定十神落点明显前景化。')}
function topicPatternText(topic){const pats=arr(topic?.patternCandidates).slice(0,3);return pats.length?pats.map(x=>`${x.tenGodZh||tenGodLabel(x.tenGodCode)} · ${patternFamily(x.patternFamily)}${x.visiblePathCount?tr(` · ${x.visiblePathCount} supported path(s)`,` · ${x.visiblePathCount} 条成格支持`):''}`).join('；'):tr('No current pattern path is required to explain this topic.','这个主题目前不需要依赖某一条格局路径才能成立。')}
function topicRelationText(topic){const rels=arr(topic?.relationshipInterfaces).slice(0,3);return rels.length?rels.map(x=>`${relation(x.type)} · ${positionThemeLabel(x.positionThemeCode)}`).join('；'):tr('No direct pillar interface is foregrounded for this topic.','这个主题目前没有直接柱位接口被前景化。')}
function topicCompositionText(topic){const copy=TOPIC_COPY[topic?.topicCode]||TOPIC_COPY.LIFE_OPERATION,carry=topic?.carryingContext||{};return tr(`${copy.lens[0]} The foreground functional mix is ${topicGroupText(topic)}. Day-Master carrying is ${strengthTendencyLabel(carry.overallTendency)}, with roots ${carry.rootCount||0}, support ${carry.supportVisible||0}, drain/consumption ${carry.outwardVisible||0}, and pressure ${carry.pressureVisible||0}.`,`${copy.lens[1]} 当前前景功能组合为：${topicGroupText(topic)}。日主承载呈「${strengthTendencyLabel(carry.overallTendency)}」，根气 ${carry.rootCount||0}、生扶 ${carry.supportVisible||0}、泄耗 ${carry.outwardVisible||0}、克 ${carry.pressureVisible||0}。`)}
