function timelineCycleCard(cycle,product){const priorityLabels=arr(cycle.priorityRefs).slice(0,2).map(ref=>timelinePriorityLabel(product,ref));const fg=arr(cycle.functionGroups).map(groupLabel);return `<article class="cx-bazi-professional-cycle"${cycle.isSelected?' data-current="true"':''}><header><small>${esc(tr(`Cycle ${cycle.cycleNumber}`,`第 ${cycle.cycleNumber} 运`))}</small>${cycle.isSelected?`<em>${esc(tr('Selected window','当前窗口'))}</em>`:''}</header><strong>${esc(`${cycle.pillar?.stem?.zh||''}${cycle.pillar?.branch?.zh||''}`)}</strong><span>${esc(`${cycle.startAge}–${cycle.endAge} · ${cycle.stemTenGod?.zh||''}`)}</span><div class="cx-bazi-cycle-groups">${fg.length?fg.map(x=>`<span>${esc(x)}</span>`).join(''):`<span>${esc(tr('Function group open','功能组待核对'))}</span>`}</div><div class="cx-bazi-cycle-topics">${timelineTopicBadges(cycle.topicActivations)}</div><footer><span>${esc(tr(`${cycle.activationEvidence?.interactionCount||0} natal interaction(s)`,`${cycle.activationEvidence?.interactionCount||0} 项原局互动`))}</span>${priorityLabels.length?`<small>${esc(priorityLabels.join(' · '))}</small>`:''}</footer></article>`}
